INSERT INTO glossary_terms (term_key, term, aliases, definition, source, verified) VALUES
  ($g$hidronefrosis$g$, $g$Hidronefrosis$g$, ARRAY[$g$pembengkakan ginjal$g$]::text[], $g$Pembengkakan satu atau kedua ginjal akibat penumpukan urin, yang terjadi ketika urin tidak dapat mengalir normal dari ginjal ke kandung kemih, baik karena sumbatan maupun aliran balik urin. Penyebab yang lazim antara lain batu ginjal, pembesaran prostat, dan refluks vesikoureter. Dapat muncul mendadak atau perlahan. Bila tidak ditangani, ginjal yang terkena dapat rusak permanen; gagal ginjal jarang terjadi selama ginjal lainnya berfungsi normal.$g$, $g$UF Health (berdasarkan MedlinePlus) — Hydronephrosis of One Kidney; Yale Medicine — Hydronephrosis; diringkas ke bahasa Indonesia$g$, false),
  ($g$hipoglikemia$g$, $g$Hipoglikemia$g$, ARRAY[$g$gula darah rendah$g$,$g$glukosa darah rendah$g$]::text[], $g$Keadaan ketika kadar glukosa darah turun terlalu rendah, umumnya di bawah 70 mg/dL, sehingga perlu tindakan untuk mengembalikannya ke rentang target. Gejala berbeda antar orang. Penanganan awal pada orang yang masih sadar adalah memberi karbohidrat cepat serap (aturan 15/15: 15 g karbohidrat, lalu cek ulang setelah 15 menit). Hipoglikemia berat adalah keadaan darurat yang membutuhkan bantuan orang lain.$g$, $g$American Diabetes Association — Low Blood Glucose (Hypoglycemia); diringkas ke bahasa Indonesia$g$, false),
  ($g$sindrom nefrotik$g$, $g$Sindrom nefrotik$g$, ARRAY[$g$nefrosis$g$]::text[], $g$Sindrom ginjal yang ditandai proteinuria berat (rentang nefrotik), hipoalbuminemia, edema, dan sering disertai hiperlipidemia. Pada dewasa, pedoman yang dipakai dalam publikasi Clinical and Experimental Nephrology (2016) mensyaratkan proteinuria ≥3,5 g/hari yang menetap dan albumin serum rendah (≤3,0 g/dL); edema penting tetapi bukan syarat mutlak, dan dislipidemia juga tidak wajib. Batas albumin dapat berbeda antar sumber.$g$, $g$Clin Exp Nephrol 2016;20:342–370 (PMC4891386); Family Practice Notebook — Nephrotic Syndrome; diringkas ke bahasa Indonesia$g$, false),
  ($g$hiperkalemia$g$, $g$Hiperkalemia$g$, ARRAY[$g$kalium tinggi$g$,$g$kadar kalium darah tinggi$g$]::text[], $g$Keadaan ketika kadar kalium dalam darah lebih tinggi dari normal (rentang acuan sekitar 3,5–5,2 mmol/L, bervariasi antar laboratorium). Sering tidak bergejala. Penyebab sejati yang paling umum berkaitan dengan ginjal. Kadar yang sangat tinggi atau perubahan EKG memerlukan penanganan darurat. Hasil tinggi palsu (pseudohiperkalemia) dapat terjadi bila sel darah pecah saat atau setelah pengambilan sampel, sehingga pemeriksaan perlu diulang.$g$, $g$MedlinePlus (NLM) — High potassium level; Mayo Clinic — High potassium (hyperkalemia); diringkas ke bahasa Indonesia$g$, false)
